<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> KNOWLEDGE_REQUEST_ERROR_CODE: </span><span style="color:#E7C58C;">&#39;knowledge_request&#39;</span><span style="color:#DCE9F2;">;</span></span>
